.theme-body.mesa-review{--inventory-border:#d1c4aa;--inventory-hover:#8f8067}
.theme-body.ev-review{--inventory-border:#c4d4c5;--inventory-hover:#8da992}
.theme-body.mt-review{--inventory-border:#d7dce5;--inventory-hover:#8b9ab8}
.theme-body.st-review{--inventory-border:#c9cbc4;--inventory-hover:#9b9f96}
.theme-body.ls-review .inventorygrid .vehicle{border-color:var(--inventory-border)!important;min-width:0}
.theme-body.ls-review .inventorygrid .vehicle:hover,.theme-body.ls-review .inventorygrid .vehicle:focus-within{border-color:var(--inventory-hover)!important;transform:none!important}
.theme-body.ls-review .inventorygrid .vehicle .vehiclephoto{position:relative;width:100%;aspect-ratio:3/2;min-height:0;overflow:hidden;flex:none}
.theme-body.ls-review .inventorygrid :is(.vehicle,.vehicle:first-child) .vehiclephoto img{position:absolute;inset:0;display:block;width:100%!important;height:100%!important;min-height:0;max-height:none;aspect-ratio:auto;object-fit:cover;object-position:center;transform:none!important}
.theme-body.ls-review:not(.mesa-review) .inventorygrid .vehicle{display:flex;flex-direction:column}
.theme-body.ls-review:not(.mesa-review) .inventorygrid .vehiclebody{display:flex;flex-direction:column;flex:1}
.theme-body.ls-review:not(.mesa-review) .inventorygrid .vehiclebottom{margin-top:auto}
.theme-body.ls-review .ls-event-vehicle>img{width:100%;height:auto!important;aspect-ratio:3/2;object-fit:cover}
