.theme-body.db-review{--inventory-border:#dfd0b8;--inventory-hover:#af9674}
/* Gallery frames follow the same theme tokens as inventory, including thumbnails. */
.theme-body.ls-review{--inventory-image-radius:24px}
.theme-body.um-review{--inventory-image-radius:10px}
.theme-body.cx-review{--inventory-image-radius:18px}
.theme-body.mesa-review{--inventory-image-radius:6px}
.theme-body.ev-review{--inventory-image-radius:23px}
.theme-body.mt-review{--inventory-image-radius:8px}
.theme-body.st-review{--inventory-image-radius:8px}
.theme-body.db-review{--inventory-image-radius:14px}
.theme-body.ls-review .richdialog .gallery-main{border:1px solid var(--inventory-border);border-radius:var(--inventory-image-radius);background:transparent;box-sizing:border-box;object-fit:cover;overflow:hidden}
.theme-body.ls-review .gallery-thumbs{padding:5px 3px 12px;gap:10px}
.theme-body.ls-review .gallery-thumbs button{padding:0;border:1px solid var(--inventory-border);border-radius:min(8px,var(--inventory-image-radius));background:transparent;overflow:hidden;line-height:0;box-sizing:border-box;box-shadow:none}
.theme-body.ls-review .gallery-thumbs button img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:cover;border:0;border-radius:0;margin:0}
.theme-body.ls-review .gallery-thumbs button[aria-current=true]{border-color:var(--inventory-hover);outline:2px solid var(--inventory-hover);outline-offset:1px}
.theme-body.ls-review .gallery-thumbs button:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.theme-body.ls-review .gallery-nav button,.theme-body.ls-review .gallery-tabs button{border:1px solid var(--inventory-border);border-radius:min(8px,var(--inventory-image-radius));background:transparent;color:inherit}
.theme-body.ls-review .richdialog .gallery-main{height:auto!important;aspect-ratio:3/2}
.theme-body.ah-review{--inventory-border:#344353;--inventory-hover:#718fa5;--inventory-image-radius:10px}
/* Interaction colors follow the active theme, never the inherited Lone Star skin.
   New reviewed themes inherit these rules through this shared stylesheet. */
.theme-body.ls-review{--interaction-accent:var(--accent);--interaction-ink:var(--buttonInk)}
.theme-body.ls-review :is(.vehicle,.person,.service-feature,.ls-event-vehicle):is(:hover,:focus-within){border-color:var(--inventory-hover)!important}
.theme-body.ls-review :is(button,a,input,select,textarea,[tabindex]):focus-visible{outline:2px solid var(--interaction-accent)!important;outline-offset:3px}
.theme-body.ls-review input:is([type=checkbox],[type=radio],[type=range]){accent-color:var(--interaction-accent)}
.theme-body.ls-review .compare-toggle{border-color:var(--inventory-border);color:var(--ink)}
.theme-body.ls-review .compare-toggle:is([aria-checked=true],[aria-pressed=true]){border-color:var(--interaction-accent)!important;background:var(--interaction-accent)!important;color:var(--interaction-ink)!important}
.theme-body.ls-review .payment-tabs button[aria-selected=true]{background:var(--interaction-accent)!important;color:var(--interaction-ink)!important;border-color:var(--interaction-accent)}
.theme-body.ls-review .choice:has(input:checked){border-color:var(--interaction-accent);box-shadow:0 0 0 1px var(--interaction-accent)}
.theme-body.ls-review .sfsteps li.current{border-color:var(--interaction-accent)}
.theme-body.ls-review .gallery-thumbs button[aria-current=true]{border-color:var(--interaction-accent);outline-color:var(--interaction-accent)}
.theme-body.ax-review{--inventory-border:#cdd2be;--inventory-hover:#7d8d5c;--inventory-image-radius:4px}
.theme-body.hb-review{--inventory-border:#c8dce8;--inventory-hover:#6ca9c9;--inventory-image-radius:18px}
.theme-body.fd-review{--inventory-border:#393939;--inventory-hover:#ac9270;--inventory-image-radius:8px}
.theme-body.vx-review{--inventory-border:#cddbd3;--inventory-hover:#79ac91;--inventory-image-radius:18px}
.theme-body.ra-review{--inventory-border:#d5d0c1;--inventory-hover:#b98c7b;--inventory-image-radius:10px}
/* Shared navigation geometry and form rhythm for all reviewed themes. */
.theme-body.ls-review{--nav-radius:24px}.theme-body.um-review{--nav-radius:5px}.theme-body.cx-review{--nav-radius:12px}.theme-body.mesa-review{--nav-radius:4px}.theme-body.ev-review{--nav-radius:14px}.theme-body.mt-review{--nav-radius:6px}.theme-body.st-review{--nav-radius:5px}.theme-body.db-review{--nav-radius:8px}.theme-body.ah-review{--nav-radius:5px}.theme-body.ax-review{--nav-radius:3px}.theme-body.hb-review{--nav-radius:24px}.theme-body.fd-review{--nav-radius:5px}.theme-body.vx-review{--nav-radius:12px}.theme-body.ra-review{--nav-radius:7px}
.theme-body.ls-review .nav .navlinks{border-radius:calc(var(--nav-radius) + 5px)!important;column-gap:3px;row-gap:10px}
.theme-body.ls-review .nav .navlinks>a,.theme-body.ls-review .nav .navlinks .jelly-blob,.theme-body.ls-review .nav .mobilemenu,.theme-body.ls-review .nav .language-switch select{border-radius:var(--nav-radius)!important}
.theme-body.ls-review .nav .navlinks>a.button{margin-inline-start:16px!important;flex-shrink:0}
