.theme-body.ls-review :is(.lead-contact,.lead-dialog,.richdialog) .inquiryfields>div>label{font-size:12px;line-height:1.45;min-height:2.9em;display:flex;align-items:flex-end;margin:0 0 9px;letter-spacing:normal}
.theme-body.ls-review :is(.lead-contact,.lead-dialog,.richdialog) .inquiryfields :is(input:not([type=checkbox]):not([type=radio]),select){min-height:46px;width:100%;box-sizing:border-box;margin:0}
