.theme-body.ls-review .inquiryfields>.inquiry-consent{align-self:end;min-height:46px;margin:0;align-items:center}
@container (max-width:1350px){.theme-body.ls-review .nav{flex-wrap:wrap}.theme-body.ls-review .nav .mobilemenu{display:block;margin-left:auto}.theme-body.ls-review .nav .navlinks{display:none;width:100%;order:5;flex-wrap:wrap;justify-content:flex-start}.theme-body.ls-review .nav .navlinks.open{display:flex}}
